/**
 * Maryland Public Angler Access Sites — enriched merge
 *
 * Two authoritative DNR layers merged into one dataset:
 *   1. Public_View_Angler_Access_Sites_ (FeatureServer/0) — 2026-04-13 pull,
 *      579 sites. Source of record for `fishTypes`, `specialReg`, and the
 *      original boat-ramp / soft-launch booleans.
 *   2. Maryland_Water_Access_Sites_Production_View (FeatureServer/0) +
 *      Public_Water_Access_2020 + WaterAccessPnt_Points — pulled 2026-04-19.
 *      513 unique sites after 50m dedupe (priority: Production View >
 *      2020 view > WaterAccessPnt). 355 of those matched existing angler
 *      entries within 250m and contributed facility metadata (owner,
 *      phone, hours, ramp lanes, ADA, parking spaces, amenities,
 *      directions). 158 had no match and are added as angler_580+.
 *
 * All three DNR services live under
 *   https://services.arcgis.com/njFNhDsUCentVYJW/ArcGIS/rest/services
 *
 * Ship count: 737 sites
 *   • 158 new since the 2026-04-13 ingest (from DNR Production View)
 *   • 488/737 carry authoritative owner/manager metadata
 *   • 486/737 carry a contact phone number
 *   • 448/737 carry driving directions
 *   • 51/737 have ADA-compliant boat ramps
 *   • 265/737 have a boat ramp (legacy flag)
 *   • 307/737 have soft / non-trailer launches (legacy flag)
 *   • 1/737 carry a fishable-reach polyline trace
 *   • 1/737 carry a precise parking coordinate
 *
 * Non-contiguous ids preserved: angler_0..angler_578 from the original 579
 * (one geometry-null record was dropped in 2026-04-13 ingest, so index 147
 * is missing). New DNR-only additions take angler_580..angler_737.
 *
 * The contract test in __tests__ asserts count, uniqueness, MD bbox, boolean
 * flags, fishableReach geometry, and the new enrichment-field invariants.
 *
 * Last updated: 2026-04-19 (DNR Production View merge; task #35)
 */

/**
 * GeoJSON-style coordinate array ordered [lng, lat]. Used for river-reach
 * tracings so Mapbox LineLayer can consume them directly without conversion.
 */
export type FishableReachCoord = [number, number];

/**
 * Linear trace of the FISHABLE stretch of a river/creek — not the surrounding
 * park polygon. When present, the fish map renders this as a dashed amber line
 * layered on top of the county polygons. When null, the access site is
 * rendered only as a point marker.
 */
export type FishableReach =
  | { type: 'LineString'; coordinates: FishableReachCoord[] }
  | { type: 'MultiLineString'; coordinates: FishableReachCoord[][] };

/**
 * Source-of-record confidence tag. 'verified' = sourced directly from a
 * DNR authoritative FeatureServer layer pulled within the last ~30 days.
 * 'approximate' reserved for future legacy-migration cases where we hand
 * coded coordinates from non-authoritative sources.
 */
export type AccessSiteConfidence = 'verified' | 'approximate';

/**
 * Ownership category from DNR Production View. Normalized uppercase.
 * "COUNY" / lowercase "County" data entry errors in the DNR layer are
 * normalized to "COUNTY" during ingest.
 */
export type OwnerType = 'STATE' | 'COUNTY' | 'MUNICIPAL' | 'FEDERAL' | 'NGO' | 'OTHER';

export type ParkingSize = 'small' | 'medium' | 'large';

export interface AnglerAccessSite {
  // --- Required identity + geometry ---
  id: string;
  name: string;
  county: string;
  waterbody: string;
  fishTypes: string;           // free-text; may be empty for sites without species metadata
  specialReg: string;          // "None" when unrestricted
  hasRamp: boolean;            // legacy flag from 2026-04-13 ingest
  hasSoftLaunch: boolean;      // legacy flag from 2026-04-13 ingest
  lat: number;
  lng: number;

  // --- Existing optionals (preserved from earlier builds) ---
  /** Optional precise coordinate of the parking lot. When set, the Directions
   *  button targets this instead of the access-point marker. */
  parkingLat?: number;
  parkingLng?: number;
  /** Optional linear trace of the fishable stretch. Rendered as a dashed
   *  amber line over the point marker. */
  fishableReach?: FishableReach | null;

  // --- Provenance + confidence (Build 7) ---
  confidence?: AccessSiteConfidence;
  source?: string;
  dnrObjectId?: number;

  // --- Ownership & contact (from DNR Production View) ---
  ownerName?: string;
  ownerType?: OwnerType;
  address?: string;
  contactPhone?: string;
  contactEmail?: string;
  contactWebsite?: string;
  hours?: string;              // e.g. "Dawn to Dusk"
  feeRequired?: boolean;

  // --- Ramp facts (authoritative DNR fields) ---
  hasBoatRamp?: boolean;       // DNR-declared; may differ from legacy hasRamp
  rampLanes?: number;
  rampSurface?: string;        // "CONCRETE" | "ASPHALT" | "n/a"
  rampWidthFt?: number;
  softAccessOnly?: boolean;
  softAccessType?: string;     // "Natural shoreline" | "Sand" | etc.

  // --- Parking ---
  parkingSurface?: string;     // "GRAVEL" | "PAVED" | "UNPAVED"
  parkingSize?: ParkingSize;
  trailerSpaces?: number;
  carSpaces?: number;

  // --- Amenities ---
  hasDock?: boolean;
  hasTransientDock?: boolean;
  boardingPiers?: number;
  hasRestroom?: boolean;
  hasTrashService?: boolean;
  hasFuel?: boolean;
  hasPumpout?: boolean;
  hasSlipRentals?: boolean;

  // --- Accessibility (ADA) ---
  adaRamp?: boolean;
  adaSoftAccess?: boolean;
  adaCarSpace?: boolean;
  adaPier?: boolean;

  // --- Vessel restrictions ---
  electricMotorsOnly?: boolean;
  largeBoatsOk?: boolean;
  vesselRestriction?: string;  // free-text, e.g. "Small non-motorized vessels only"
  wingWalls?: boolean;

  // --- Free-text ---
  comments?: string;
  directions?: string;
}

